const maxLine = 64 * 1024

func Serve(ctx context.Context, l net.Listener, s *store.Store) error {
    var (
        mu sync.Mutex
        conns = make(map[net.Conn]struct{})
        wg sync.WaitGroup
    )
    finished := make(chan struct{})
    go func() {
        <-ctx.Done()
        l.Close()
        mu.Lock()
        for c := range conns { c.Close() }
        mu.Unlock()
        wg.Wait()
        close(finished)
    }()

    for {
        c, err := l.Accept()
        if err != nil {
            if ctx.Err() != nil {
                <-finished
                return nil
            }
            return err
        }
        mu.Lock()
        conns[c] = struct{}{}
        mu.Unlock()
        wg.Add(1)
        go func(c net.Conn) {
            defer wg.Done()
            defer c.Close()
            defer func() { mu.Lock(); delete(conns, c); mu.Unlock() }()
            serveConn(c, s)
        }(c)
    }
}

func serveConn(c net.Conn, s *store.Store) {
    br := bufio.NewReader(c)
    var out bufio.Writer? // writing directly is OK but flushing each response
    for {
        line, err := br.ReadString('\n')
        if err != nil { return }
        if len(line) > maxLine {
            c.Write([]byte("-ERR line too long\n"))
            return
