function.arguments:
{"content":"// Package store implements a thread-safe in-memory key-value store
// with per-key expirations, glob key matching and JSON snapshots.
package store

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

// ErrNotInteger is returned by Incr when the stored value is not a
// base-10 integer.
var ErrNotInteger = errors.New("value is not an integer")

// Clock returns the current time.
type Clock func() time.Time

type entry struct {
	value string
	exp   time.Time // zero means no expiry
}

// Store is a concurrent key-value store with optional key expirations.
type Store struct {
	mu    sync.Mutex
	clock Clock
	m     map[string]entry
}

// New creates an empty Store. A nil clock defaults to time.Now.
func New(clock Clock) *Store {
	if clock == nil {
		clock = time.Now
	}
	return &Store{clock: clock, m: make(map[string]entry)}
}

func (s *Store) alive(e entry) bool {
	return e.exp.IsZero() || s.clock().Before(e.exp)
}

// Set stores value under key. ttl <= 0 means no expiry. Set always
// replaces both the value and the ttl.
func (s *Store) Set(key, value string, ttl time.Duration) {
	s.mu.Lock()
	defer s.mu.Unlock()
	var exp time.Time
	if ttl > 0 {
		exp = s.clock().Add(ttl)
	}
	s.m[key] = entry{value: value, exp: exp}
}

// Get returns the value of key, or ok == false if the key is missing
// or expired.
func (s *Store) Get(key string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.m[key]
	if !ok || !s.alive(e) {
		return "", false
	}
	return e.value, true
}

// Del removes the given keys and returns how many of them existed
// (were live) and were removed.
func (s *Store) Del(keys ...string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for _, key := range keys {
		if e, ok := s.m[key]; ok && s.alive(e) {
			delete(s.m, key)
			n++
		}
	}
	return n
}

// Exists reports whether key is present and not expired.
func (s *Store) Exists(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.m[key]
	return ok && s.alive(e)
}

// Expire sets a new expiration on key, replacing any existing one.
// It returns false if the key is missing (or expired); ttl <= 0
// deletes the key and returns true.
func (s *Store) Expire(key string, ttl time.Duration) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.m[key]
	if !ok || !s.alive(e) {
		return false
	}
	if ttl <= 0 {
		delete(s.m, key)
		return true
	}
	e.exp = s.clock().Add(ttl)
	s.m[key] = e
	return true
}

// Persist removes the expiration of key. It returns true only if the
// key existed AND had an expiry.
func (s *Store) Persist(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.m[key]
	if !ok || !s.alive(e) || e.exp.IsZero() {
		return false
	}
	e.exp = time.Time{}
	s.m[key] = e
	return true
}

// TTL reports the remaining time to live of key: -2 as
// time.Duration if the key is missing or expired, -1 if it has no
// expiry, otherwise the remaining time (> 0).
func (s *Store) TTL(key string) time.Duration {
	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.m[key]
	if !ok || !s.alive(e) {
		return time.Duration(-2)
	}
	if e.exp.IsZero() {
		return time.Duration(-1)
	}
	return e.exp.Sub(s.clock())
}

// Incr adds by to the integer value of key (a missing or expired key
// counts as 0) and stores the result, keeping any existing ttl.
// It returns ErrNotInteger if the current value is not a base-10
// int64.
func (s *Store) Incr(key string, by int64) (int64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	var v int64
	var exp time.Time
	if e, ok := s.m[key]; ok && s.alive(e) {
		n, err := strconv.ParseInt(e.value, 10, 64)
		if err != nil {
			return 0, ErrNotInteger
		}
		v = n
		exp = e.exp
	}
	s.m[key] = entry{value: strconv.FormatInt(v+by, 10), exp: exp}
	return v + by, nil
}

// Keys returns the live keys matching the glob pattern, sorted
// ascending.
func (s *Store) Keys(pattern string) []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	var out []string
	for k, e := range s.m {
		if s.alive(e) && Match(pattern, k) {
			out = append(out, k)
		}
	}
	sort.Strings(out)
	return out
}

// Len returns the number of live (non-expired) keys.
func (s *Store) Len() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for _, e := range s.m {
		if s.alive(e) {
			n++
		}
	}
	return n
}

// snapshot is the on-disk format of a snapshot.
type snapshot struct {
	Version int `json:"version"`
	// Entries holds the entries sorted by key; it is non-nil.
	Entries []snapEntry `json:"entries"`
}

type snapEntry struct {
	K   string `json:"k"`
	V   string `json:"v"`
	Exp int64  `json:"exp"` // unix milliseconds, 0 = no expiry
}

// Save writes a JSON snapshot of the live entries to w.
func (s *Store) Save(w io.Writer) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.clock()
	snap := snapshot{Version: 1, Entries: []snapEntry{}}
	for k, e := range s.m {
		if !s.alive(e) {
			continue
		}
		se := snapEntry{K: k, V: e.value}
		if !e.exp.IsZero() {
			se.Exp = e.exp.UnixMilli()
		}
		snap.Entries = append(snap.Entries, se)
	}
	sort.Slice(snap.Entries, func(i, j int) bool { return snap.Entries[i].K < snap.Entries[j].K })
	data, err := json.Marshal(snap)
	if err != nil {
		return err
	}
	_, err = w.Write(append(data, '\n'))
	return err
}

// Load replaces all contents of the store with the JSON snapshot
// read from r. Snapshots with any version other than 1 are rejected
// with an error. Entries already expired at load time are dropped.
func (s *Store) Load(r io.Reader) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	var snap snapshot
	if err := json.Unmarshal(data, &snap); err != nil {
		return err
	}
	if snap.Version != 1 {
		return fmt.Errorf("unsupported snapshot version %d", snap.Version)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.clock().UnixMilli()
	m := make(map[string]entry, len(snap.Entries))
	for _, se := range snap.Entries {
		if se.Exp > 0 && se.Exp <= now {
			continue // already expired at load time
		}
		var exp time.Time
		if se.Exp > 0 {
			exp = time.UnixMilli(se.Exp)
		}
		m[se.K] = entry{value: se.V, exp: exp}
	}
	s.m = m
	return nil
}

// Match reports whether key matches the glob pattern. The whole key
// must match. Supported: '*' any sequence (including empty),
// '?' exactly one character, '[abc]' one of a set, '[a-z]' a range,
// '[^a]'/'[!a]' negation and backslash-escaped literals.
func Match(pattern, key string) bool {
	for len(pattern) > 0 {
		switch pattern[0] {
		case '*':
			pattern = strings.TrimLeft(pattern, "*")
			if len(pattern) == 0 {
				return true
			}
			for i := 0; i <= len(key); i++ {
				if Match(pattern, key[i:]) {
					return true
				}
			}
			return false
		case '?':
			if len(key) == 0 {
				return false
			}
			key = key[1:]
			pattern = pattern[1:]
		case '\\':
			if len(pattern) < 2 {
				return false // trailing backslash
			}
			if len(key) == 0 || key[0] != pattern[1] {
				return false
			}
			key = key[1:]
			pattern = pattern[2:]
		case '[':
			end := strings.IndexByte(pattern[1:], ']')
			if end < 0 {
				return false // unterminated character class
			}
			end++ // index of ']' within pattern
			if len(key) == 0 {
				return false
			}
			j := 1
			neg := false
			if j < end && (pattern[j] == '^' || pattern[j] == '!') {
				neg = true
				j++
			}
			found := false
			c := key[0]
			for k := j; k < end; {
				lo := pattern[k]
				k++
				if k+1 < end && pattern[k] == '-' {
					hi := pattern[k+1]
					k += 2
					if lo <= c && c <= hi {
						found = true
						break
					}
				} else if c == lo {
					found = true
					break
				}
			}
			if found == neg {
				return false
			}
			key = key[1:]
			pattern = pattern[end+1:]
		default:
			if len(key) == 0 || key[0] != pattern[0] {
				return false
			}
			key = key[1:]
			pattern = pattern[1:]
		}
	}
	return len(key) == 0
}
