func TestSetGet(t *testing.T) {
	c, now := fixedClock()
	s := New(c)
	s.Set("a", "1", 0)
	if v, ok := s.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q,%v", v, ok)
	}
	if _, ok := s.Get("nope"); ok {
		t.Fatal("missing key reported present")
	}
	// Set always replaces both value and ttl.
	s.Set("a", "2", 10*time.Second)
	if v, ok := s.Get("a"); !ok || v != "2" {
		t.Fatalf("Get(a) after re-Set = %q,%v", v, ok)
	}
	if got := s.TTL("a"); got != 10*time.Second {
		t.Fatalf("TTL(a) = %v", got)
	}
	s.Set("a", "3", 0)
	if got := s.TTL("a"); got != -1 {
		t.Fatalf("TTL(a) after ttl-less Set = %v, want -1", got)
	}
}

func TestExpiry(t *testing.T) {
	c, now := fixedClock()
	s := New(c)
	s.Set("k", "v", time.Second)
	if !s.Exists("k") || s.Len() != 1 {
		t.Fatal("key should be alive before deadline")
	}
	// now == deadline-1ns: alive.
	*now = (*now).Add(time.Second - time.Nanosecond)
	if !s.Exists("k") || s.Len() != 1 || s.Get("k") != ("v", true) {
		t.Fatal("key must be alive strictly before deadline")
	}
	v, _ := s.Get("k")
	if v != "v" {
		t.Fatal("value")
	}
	// now == deadline: expired.
	*now = (*now).Add(time.Nanosecond)
	if s.Exists("k") || s.Len() != 0 || s.Get("k") == ("v", true) {
		t.Fatal("key must be expired at now >= deadline")
	}
	if got := s.TTL("k"); got != -2 {
		t.Fatalf("TTL(expired) = %v, want -2", got)
	}
}

