	c, _ := fixedClock()
	s := New(c)
	s.Set("user:1", "a", 0)
	s.Set("user:2", "b", 0)
	s.Set("users", "c", 0)
	s.Set("item", "d", 0)
	s.Set("gone", "x", time.Second)
	cases := []struct{ pattern, want string }{
		{"user:1", "user:1"},
		{"user:*", "user:1,user:2"},
		{"*user*", "user:1,user:2,users"},
		{"*", "item,user:1,user:2,users"},
		{"user?", "user:"}, // no, '?' needs exactly one more char: user? matches nothing among these? user: has ':' after "user" -> "user:" is 5 chars; pattern "user?" matches len-5 keys starting user: user:1 is len 6. none.
		{"users?", "users"},
		{"us?s", "users"},
		{"[iu]ser*?*", ""},
		{"[!u]*", "item"},
		{"[^i]*", "user:1,user:2,users"},
		{"u*es", "users"},
		{"user\\:1", "user:1"},
		{"[a-z]*", "item,user:1,user:2,users"},
		{"[a-c]*", "item"},
		{"it?m", "item"},
	}
	for _, tc := range cases {
		got := s.Keys(tc.pattern)
		if strings.Join(got, ",") != tc.want {
			t.Errorf("Keys(%q) = %v, want %v", tc.pattern, got, strings.Split(tc.want, ","))
		}
	}
