func TestMatchUnit(t *testing.T) {
	cases := []struct {
		pattern, key string
		want         bool
	}{
		{"abc", "abc", true},
		{"abc", "abd", false},
		{"a*c", "ac", true},
		{"a*c", "azc", true},
		{"a*c", "ab", false},
		{"*c", "abc", true},
		{"*", "anything/at/all", true},
		{"**", "x", true},
		{"a?c", "abc", true},
		{"a?c", "ac", false},
		{"[abc]d", "ad", true},
		{"[abc]d", "xd", false},
		{"[a-z]d", "kd", true},
		{"[a-z]d", "1d", false},
		{"[^a]d", "bd", true},
		{"[^a]d", "ad", false},
		{"[!a]d", "bd", true},
		{"[!a]d", "ad", false},
		{`a\.b`, "a.b", true},
		{`a\.b`, "axb", false},
		{"a.b", "a.b", true},
		{"[abc", "abc", false}, // unterminated class
		{"\\", "a", false},      // trailing backslash
		{"a\\", "a", false},     // trailing backslash
	}
	for _, tc := range cases {
		if got := Match(tc.pattern, tc.key); got != tc.want {
			t.Errorf("Match(%q,%q) = %v, want %v", tc.pattern, tc.key, got, tc.want)
		}
	}
}

func TestSaveLoad(t *testing.T) {
	c, now := fixedClock()
	s := New(c)
	s.Set("a", "1", 10*time.Minute)
	s.Set("b", "2", 0)
	s.Set("gone", "x", time.Second)
	var buf bytes.Buffer
	if err := s.Save(&buf); err != nil {
		t.Fatal(err)
	}
	got := buf.String()
	want := `{"version":1,"entries":[{"k":"a","v":"1","exp":` + strconvMilli(*now.Add(10*time.Minute)) + `},{"k":"b","v":"2","exp":0}]}` + "\n"
	if got != want {
		t.Fatalf("Save = %s, want %s", got, want)
	}

	// Round-trip.
	s2 := New(c)
	if err := s2.Load(strings.NewReader(got)); err != nil {
		t.Fatal(err)
	}
	if v, ok := s2.Get("a"); !ok || v != "1" {
		t.Fatalf("reloaded a = %q,%v", v, ok)
	}
	if got := s2.TTL("a"); got != 10*time.Minute {
		t.Fatalf("reloaded TTL(a) = %v", got)
	}
	if got := s2.Len(); got != 2 {
		t.Fatalf("Len = %d, want 2 (expired dropped)", got)
	}
	// Load replaces all contents.
	s2.Set("zzz", "z", 0)
	if err := s2.Load(strings.NewReader(got)); err != nil {
		t.Fatal(err)
	}
	if s2.Exists("zzz") {
		t.Fatal("Load should replace all contents")
	}

	// Wrong version rejected.
	if err := s2.Load(strings.NewReader(`{"version":2,"entries":[]}`)); err == nil {
		t.Fatal("Load of version 2 should fail")
	}

	// Entries already expired at load time are dropped.
	*now = *now.Add(2 * time.Second)
	s3 := New(c)
	if err := s3.Load(strings.NewReader(got)); err != nil {
		t.Fatal(err)
	}
	if s3.Exists("a") {
		t.Fatal("a was expired at load time and must be dropped")
	}
	if !s3.Exists("b") {
		t.Fatal("b has no expiry and must survive")
	}

	// Bad JSON rejected.
	if err := s3.Load(strings.NewReader("{nope")); err == nil {
		t.Fatal("Load of bad JSON should fail")
	}
}

