		t.Fatal(err)
	}
	if got := s.TTL("m"); got != time.Hour {
		t.Fatalf("TTL(m) after Incr = %v, want 1h", got)
	}
	s.Set("s", "abc", 0)
	if _, err := s.Incr("s", 1); !errors.Is(err, ErrNotInteger) {
		t.Fatalf("Incr on non-integer = %v, want ErrNotInteger", err)
	}
	s.Set("bad", "12x", 0)
	if _, err := s.Incr("bad", 1); !errors.Is(err, ErrNotInteger) {
		t.Fatalf("Incr on non-integer value = %v, want ErrNotInteger", err)
	}
	// Expired key counts as 0 and loses its ttl.
	s.Set("e", "7", time.Second)
	*now = *now.Add(2 * time.Second)
	if v, err := s.Incr("e", 1); err != nil || v != 1 {
		t.Fatalf("Incr expired = %d,%v", v, err)
	}
	if got := s.TTL("e"); got != -1 {
		t.Fatalf("TTL(e) after incr of expired = %v, want -1", got)
