func TestKeys(t *testing.T) {
	c, _ := fixedClock()
	s := New(c)
	s.Set("user:1", "a", 0)
	s.Set("user:2", "b", 0)
	s.Set("users", "c", 0)
	s.Set("item", "d", 0)
	s.Set("gone", "x", time.Second) // expired: never matched
	cases := []struct{ pattern, want string }{
		{"user:1", "user:1"},
		{"user:*", "user:1,user:2"},
		{"*user*", "user:1,user:2,users"},
		{"*", "item,user:1,user:2,users"},
		{"users?", "users"},
		{"us?s", "users"},
		{"[iu]*", "item,users"},
		{"[!u]*", "item"},
		{"[^i]*", "user:1,user:2,users"},
		{"u*es", "users"},
		{`user\:1`, "user:1"},
		{"[a-z]*", "item,user:1,user:2,users"},
		{"[a-c]*", "item"},
		{"it?m", "item"},
		{"gone", ""},
	}
	for _, tc := range cases {
		got := s.Keys(tc.pattern)
		if strings.Join(got, ",") != tc.want {
			t.Errorf("Keys(%q) = %v, want [%s]", tc.pattern, got, tc.want)
		}
	}
}

