	cases := []struct {
		pattern, key string
		want         bool
	}{
		{"abc", "abc", true},
		{"abc", "abd", false},
		{"abc", "abcd", false},
		{"a*c", "ac", true},
		{"a*c", "azc", true},
		{"a*c", "ab", false},
		{"*c", "abc", true},
		{"*", "anything/at/all", true},
		{"**", "x", true},
		{"a?c", "abc", true},
		{"a?c", "ac", false},
		{"a?c", "abbc", false},
		{"[abc]d", "ad", true},
		{"[abc]d", "xd", false},
		{"[a-z]d", "kd", true},
		{"[a-z]d", "1d", false},
		{"[^a]d", "bd", true},
		{"[^a]d", "ad", false},
		{"[!a]d", "bd", true},
		{"[!a]d", "ad", false},
		{`a\.b`, "a.b", true},
		{`a\.b`, "axb", false},
		{"a.b", "a.b", true},
		{"[abc", "abc", false},  // unterminated class
		{"\\", "a", false},       // trailing backslash
		{"a\\", "a", false},      // trailing backslash
		{"x\\[abc", "x[abc", true},
	}
