func milli(t time.Time) string { return strconv.FormatInt(t.UnixMilli(), 10) }

func TestSaveLoad(t *testing.T) {
	c, now := fixedClock()
	s := New(c)
	s.Set("a", "1", 10*time.Minute)
	s.Set("b", "2", 0)
	s.Set("gone", "x", time.Second)
	var buf bytes.Buffer
	if err := s.Save(&buf); err != nil {
		t.Fatal(err)
	}
	got := buf.String()
	want := `{"version":1,"entries":[{"k":"a","v":"1","exp":` + milli(*now.Add(10*time.Minute)) + `},{"k":"b","v":"2","exp":0}]}` + "\n"
	if got != want {
		t.Fatalf("Save =\n%s\nwant\n%s", got, want)
	}

	// Round-trip.
	s2 := New(c)
	if err := s2.Load(strings.NewReader(got)); err != nil {
		t.Fatal(err)
	}
	if v, ok := s2.Get("a"); !ok || v != "1" {
		t.Fatalf("reloaded a = %q,%v", v, ok)
	}
	if t2 := s2.TTL("a"); t2 != 10*time.Minute {
		t.Fatalf("reloaded TTL(a) = %v, want 10m", t2)
	}
	if got := s2.Len(); got != 2 {
		t.Fatalf("Len = %d, want 2 (expired dropped)", got)
	}
	// Load replaces all contents.
	s2.Set("zzz", "z", 0)
	if err := s2.Load(strings.NewReader(got)); err != nil {
		t.Fatal(err)
	}
	if s2.Exists("zzz") {
		t.Fatal("Load should replace all contents")
	}

	// Wrong version rejected.
	if err := s2.Load(strings.NewReader(`{"version":2,"entries":[]}`)); err == nil {
		t.Fatal("Load of version 2 should fail")
	}

	// Entries already expired at load time are dropped.
	*now = *now.Add(2 * time.Second)
	s3 := New(c)
	if err := s3.Load(strings.NewReader(got)); err != nil {
		t.Fatal(err)
	}
	if s3.Exists("a") {
		t.Fatal("a was expired at load time and must be dropped")
	}
	if !s3.Exists("b") {
		t.Fatal("b has no expiry and must survive")
	}

	// Bad JSON rejected.
	if err := s3.Load(strings.NewReader("{nope")); err == nil {
		t.Fatal("Load of bad JSON should fail")
	}

	// Save of an empty store.
	s4 := New(c)
	var b4 bytes.Buffer
	if err := s4.Save(&b4); err != nil {
		t.Fatal(err)
	}
	if b4.String() != `{"version":1,"entries":[]}`+"\n" {
		t.Fatalf("empty Save = %s", b4.String())
	}
}

