{"content":"// Package proto implements the line protocol on top of the store.
package proto

import (
	"strconv"
	"strings"

	"example.com/kv/store"
)

// Exec parses one request line (a trailing \n and optional \r are
// ignored) and returns the full response, including the trailing \n.
func Exec(s *store.Store, line string) string {
	line = strings.TrimSuffix(line, "\n")
	line = strings.TrimSuffix(line, "\r")

	tokens, err := tokenize(line)
	if err != nil {
		return errSyntax
	}
	if len(tokens) == 0 {
		return "-ERR empty command\n"
	}
	name := strings.ToLower(tokens[0])
	args := tokens[1:]

	switch name {
	case "ping":
		if len(args) != 0 {
			return errArity(name)
		}
		return "+PONG\n"
	case "set":
		return execSet(s, args)
	case "get":
		if len(args) != 1 {
			return errArity(name)
		}
		if v, ok := s.Get(args[0]); ok {
			return formatValue(v)
		}
		return formatNil()
	case "del":
		if len(args) < 1 {
			return errArity(name)
		}
		return formatInt(s.Del(args...))
	case "exists":
		if len(args) != 1 {
			return errArity(name)
		}
		if s.Exists(args[0]) {
			return ":1\n"
		}
		return ":0\n"
	case "expire":
		if len(args) != 2 {
			return errArity(name)
		}
		sec, err := parseSeconds(args[1])
		if err != nil {
			return err
		}
		return formatIntBool(s.Expire(args[0], sec))
	case "persist":
		if len(args) != 1 {
			return errArity(name)
		}
		return formatIntBool(s.Persist(args[0]))
	case "ttl":
		if len(args) != 1 {
			return errArity(name)
		}
		return formatInt(ttlSeconds(s, args[0]))
	case "incr":
		if len(args) != 1 {
			return errArity(name)
		}
		return execIncr(s, args[0], 1)
	case "incrby":
		if len(args) != 2 {
			return errArity(name)
		}
		by, err := strconv.ParseInt(args[1], 10, 64)
		if err != nil {
			return errNotInteger
		}
		return execIncr(s, args[0], by)
	case "keys":
		if len(args) != 1 {
			return errArity(name)
		}
		return formatArray(s.Keys(args[0]))
	case "dbsize":
		if len(args) != 0 {
			return errArity(name)
		}
		return formatInt(s.Len())
	default:
		return "-ERR unknown command '" + tokens[0] + "'\n"
	}
}

const (
	errSyntax     = "-ERR syntax error\n"
	errNotInteger = "-ERR value is not an integer\n"
)

func errArity(name string) string {
	return "-ERR wrong number of arguments for '" + name + "'\n"
}

func execSet(s *store.Store, args []string) string {
	if len(args) != 2 && len(args) != 4 {
		return errArity("set")
	}
	if len(args) == 4 {
		if !strings.EqualFold(args[2], "EX") {
			return errSyntax
		}
		sec, err := parseSeconds(args[3])
		if err != nil {
			return err
		}
		if sec <= 0 {
			return errSyntax
		}
		s.Set(args[0], args[1], sec)
	} else {
		s.Set(args[0], args[1], 0)
	}
	return "+OK\n"
}

func parseSeconds(tok string) (seconds, string) {
	n, err := strconv.ParseInt(tok, 10, 64)
	if err != nil {
		return 0, errNotInteger
	}
	return n * durationSecond, ""
}

// execIncr returns the formatted integer result or the not-integer
// error response.
func execIncr(s *store.Store, key string, by int64) string {
	v, err := s.Incr(key, by)
	if err != nil {
		return errNotInteger
	}
	return formatInt(v)
}

// ttlSeconds converts a store TTL into the protocol's integer
// seconds, rounded up.
func ttlSeconds(s *store.Store, key string) int64 {
	switch rem := s.TTL(key); rem {
	case -2:
		return -2
	case -1:
		return -1
	}
	// rem > 0; round up to whole seconds.
	return (int64(rem) + int64(durationSecond) - 1) / int64(durationSecond)
}

var durationSecond = timeSecond

func formatInt(n int64) string {
	return ":" + strconv.FormatInt(n, 10) + "\n"
}

func formatIntBool(b bool) string {
	if b {
		return ":1\n"
	}
	return ":0\n"
}

func formatNil() string { return "$nil\n" }

func needsQuote(v string) bool {
	if v == "" {
		return true
	}
	for i := 0; i < len(v); i++ {
		switch v[i] {
		case ' ', '\t', '"', '\\', '\n':
			return true
		}
	}
	return false
}

func quote(v string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(v); i++ {
		switch c := v[i]; c {
		case '"', '\\':
			b.WriteByte('\\')
			b.WriteByte(c)
		case '\n':
			b.WriteString(`\n`)
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func formatValue(v string) string {
	if needsQuote(v) {
		return "$" + quote(v) + "\n"
	}
	return "$" + v + "\n"
}

func formatArray(vals []string) string {
	var b strings.Builder
	b.WriteString("*" + strconv.Itoa(len(vals)) + "\n")
	for _, v := range vals {
		b.WriteString(formatValue(v))
	}
	return b.String()
}

var errSyntaxError = errorsNew("syntax error")

func tokenize(line string) ([]string, error) {
	var tokens []string
	i := 0
	for i < len(line) {
		// Skip separators (one or more spaces/tabs).
		for i < len(line) && (line[i] == ' ' || line[i] == '\t') {
			i++
		}
		if i >= len(line) {
			break
		}
		if line[i] == '"' {
			// Quoted token.
			var b strings.Builder
			i++
			for i < len(line) && line[i] != '"' {
				if line[i] == '\\' && i+1 < len(line) {
					switch line[i+1] {
					case '"':
						b.WriteByte('"')
					case '\\':
						b.WriteByte('\\')
					case 'n':
						b.WriteByte('\n')
					default:
						b.WriteByte(line[i+1])
					}
					i += 2
				} else {
					b.WriteByte(line[i])
					i++
				}
			}
			if i >= len(line) {
				return nil, errSyntaxError // unterminated quote
			}
			i++ // skip closing quote
			// Unquoted tail of the token, if any.
			for i < len(line) && line[i] != ' ' && line[i] != '\t' {
				b.WriteByte(line[i])
				i++
			}
			tokens = append(tokens, b.String())
		} else {
			start := i
			for i < len(line) && line[i] != ' ' && line[i] != '\t' {
				i++
			}
			tokens = append(tokens, line[start:i])
		}
	}
	return tokens, nil
}
