{"content":"package proto

import (
	"strings"
	"testing"
	"time"

	"example.com/kv/store"
)

func fixedClock() (store.Clock, *time.Time) {
	now := time.Date(2025, 1, 1, 12, 0, 0, 0, time.UTC)
	p := &now
	c := func() time.Time { return *p }
	return c, p
}

func TestBasic(t *testing.T) {
	c, _ := fixedClock()
	s := store.New(c)
	cases := []struct{ in, want string }{
		{"PING\n", "+PONG\n"},
		{"ping", "+PONG\n"},
		{"  PING\t", "+PONG\n"},
		{"", "-ERR empty command\n"},
		{"\n", "-ERR empty command\n"},
		{"   \t ", "-ERR empty command\n"},
		{"FOO bar", "-ERR unknown command 'FOO bar'\n"}, // token includes rest of line
		{"FOOBAR", "-ERR unknown command 'FOOBAR'\n"},
		{"  fOoBaR ", "-ERR unknown command 'fOoBaR'\n"},
		{"GET", "-ERR wrong number of arguments for 'get'\n"},
		{"GET a b", "-ERR wrong number of arguments for 'get'\n"},
		{"SET a", "-ERR wrong number of arguments for 'set'\n"},
		{"SET a b c", "-ERR wrong number of arguments for 'set'\n"},
		{"DEL", "-ERR wrong number of arguments for 'del'\n"},
		{"DBSIZE 1", "-ERR wrong number of arguments for 'dbsize'\n"},
		{"INCRBY a", "-ERR wrong number of arguments for 'incrby'\n"},
		{"GET \"unterminated", "-ERR syntax error\n"},
		{"SET a b FOO 5", "-ERR syntax error\n"},
		{"SET a b EX 0", "-ERR syntax error\n"},
		{"SET a b EX -3", "-ERR syntax error\n"},
		{"SET a b EX x", "-ERR value is not an integer\n"},
		{"EXPIRE a xyz", "-ERR value is not an integer\n"},
		{"INCRBY a xyz", "-ERR value is not an integer\n"},
	}
	for _, tc := range cases {
		if got := Exec(s, tc.in); got != tc.want {
			t.Errorf("Exec(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

func TestSetGet(t *testing.T) {
	s := store.New(nil)
	if got := Exec(s, "SET a b"); got != "+OK\n" {
		t.Fatal(got)
	}
	if got := Exec(s, "GET a"); got != "$b\n" {
		t.Fatalf("GET a = %q", got)
	}
	if got := Exec(s, "GET missing"); got != "$nil\n" {
		t.Fatalf("GET missing = %q", got)
	}
	// Quoted values with spaces/escapes/newlines.
	cases := []struct{ set, get string }{
		{`SET k "hello world"`, `$"hello world"\n`},
		{`SET k ""`, `$""\n`},
		{`SET k "line\nbreak"`, `$"line\nbreak"\n`},
		{`SET k "qu\"ote"`, `$"qu\"ote"\n`},
		{`SET k "back\\slash"`, `$"back\\slash"\n`},
		{`SET k ta\tb`, `$"ta\tb"\n`},
		{`SET k plain`, `$plain\n`},
	}
	for _, tc := range cases {
		if got := Exec(s, tc.set); got != "+OK\n" {
			t.Fatalf("%s = %q", tc.set, got)
		}
		if got := Exec(s, "GET k"); got != tc.get {
			t.Fatalf("GET k after %s = %q, want %q", tc.set, got, tc.get)
		}
	}
	// Repeated spaces and tabs as separators.
	if got := Exec(s, "GET   k"); got != `$"hello world"\n` && got != `$"ta\tb"\n` {
		t.Fatalf("GET with multi-space = %q", got)
	}
	// EX option.
	c, now := fixedClock()
	s2 := store.New(c)
	if got := Exec(s2, "SET t v EX 5"); got != "+OK\n" {
		t.Fatal(got)
	}
	*now = (*now).Add(5 * time.Second)
	if got := Exec(s2, "GET t"); got != "$nil\n" {
		t.Fatalf("GET t after expiry = %q", got)
	}
}

func TestDelExistsExpirePersist(t *testing.T) {
	s := store.New(nil)
	Exec(s, "SET a 1")
	Exec(s, "SET b 2")
	if got := Exec(s, "DEL a missing b"); got != ":2\n" {
		t.Fatalf("DEL = %q", got)
	}
	if got := Exec(s, "EXISTS a"); got != ":0\n" {
		t.Fatalf("EXISTS a = %q", got)
	}
	if got := Exec(s, "EXISTS b"); got != ":1\n" {
		t.Fatalf("EXISTS b = %q", got)
	}
	if got := Exec(s, "EXPIRE missing 5"); got != ":0\n" {
		t.Fatalf("EXPIRE missing = %q", got)
	}
	if got := Exec(s, "EXPIRE b 5"); got != ":1\n" {
		t.Fatalf("EXPIRE b = %q", got)
	}
	if got := Exec(s, "PERSIST b"); got != ":1\n" {
		t.Fatalf("PERSIST b = %q", got)
	}
	if got := Exec(s, "PERSIST b"); got != ":0\n" {
		t.Fatalf("PERSIST b again = %q", got)
	}
}

func TestTTL(t *testing.T) {
	c, now := fixedClock()
	s := store.New(c)
	Exec(s, "SET a 1")
	Exec(s, "SET b 2 EX 10")
	if got := Exec(s, "TTL a"); got != "-1\n" {
		t.Fatalf("TTL a = %q", got)
	}
	if got := Exec(s, "TTL missing"); got != "-2\n" {
		t.Fatalf("TTL missing = %q", got)
	}
	// 10s - 5s = 5s remaining exactly.
	*now = (*now).Add(5 * time.Second)
	if got := Exec(s, "TTL b"); got != ":5\n" {
		t.Fatalf("TTL b = %q, want :5", got)
	}
	// 10s - 5.2s = 4.8s remaining → rounds up to 5.
	*now = (*now).Add(1200 * time.Millisecond)
	if got := Exec(s, "TTL b"); got != ":5\n" {
		t.Fatalf("TTL b (round up) = %q, want :5", got)
	}
	// Fully expired.
	*now = (*now).Add(10 * time.Second)
	if got := Exec(s, "TTL b"); got != "-2\n" {
		t.Fatalf("TTL b expired = %q", got)
	}
}

func TestIncr(t *testing.T) {
	s := store.New(nil)
	if got := Exec(s, "INCR n"); got != ":1\n" {
		t.Fatalf("INCR new = %q", got)
	}
	if got := Exec(s, "INCR n"); got != ":2\n" {
		t.Fatalf("INCR = %q", got)
	}
	if got := Exec(s, "INCRBY n 5"); got != ":7\n" {
		t.Fatalf("INCRBY = %q", got)
	}
	if got := Exec(s, "INCRBY n -3"); got != ":4\n" {
		t.Fatalf("INCRBY neg = %q", got)
	}
	Exec(s, `SET s "abc"`)
	if got := Exec(s, "INCR s"); got != "-ERR value is not an integer\n" {
		t.Fatalf("INCR non-int = %q", got)
	}
}

func TestKeysDbsize(t *testing.T) {
	s := store.New(nil)
	Exec(s, "SET a 1")
	Exec(s, `SET "b c" 2`)
	Exec(s, "SET bb 3")
	if got := Exec(s, "DBSIZE"); got != ":3\n" {
		t.Fatalf("DBSIZE = %q", got)
	}
	if got := Exec(s, "KEYS *"); got != "*3\n$a\n$\"b c\"\n$bb\n" {
		t.Fatalf("KEYS * = %q", got)
	}
	if got := Exec(s, "KEYS z*"); got != "*0\n" {
		t.Fatalf("KEYS z* = %q", got)
	}
	if got := Exec(s, `KEYS "b ?"`); got != `*"b c"\n` {
		t.Fatalf("KEYS quoted = %q", got)
	}
}

func TestRoundTrip(t *testing.T) {
	// A full conversation.
	s := store.New(nil)
	script := []struct{ in, want string }{
		{"PING", "+PONG\n"},
		{"SET user:1 alice", "+OK\n"},
		{"GET user:1", "$alice\n"},
		{"DEL user:1", ":1\n"},
		{"GET user:1", "$nil\n"},
		{"SET \"sp ace\" v1", "+OK\n"},
		{"KEYS sp*", "*1\n$\"sp ace\"\n"},
	}
	for _, tc := range script {
		if got := Exec(s, tc.in); got != tc.want {
			t.Errorf("Exec(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

func TestQuoteUnit(t *testing.T) {
	cases := []struct {
		in, out string
		quoted  bool
	}{
		{"abc", "abc", false},
		{"a b", `"a b"`, true},
		{"a\tb", `"a\tb"`, true},
		{"a\"b", `"a\"b"`, true},
		{`a\b`, `"a\\b"`, true},
		{"a\nb", `"a\nb"`, true},
		{"", `""`, true},
		{`"`, `"\"\""`, true},
	}
	for _, tc := range cases {
		got := formatValue(tc.in)
		want := "$" + tc.out + "\n"
		if got != want {
			t.Errorf("formatValue(%q) = %q, want %q", tc.in, got, want)
		}
	}
	if !strings.Contains(formatValue("a\nb"), `\n`) {
		t.Error("newline must be escaped")
	}
}
