{"content":"// Package server serves the line protocol over TCP.
package server

import (
	"bufio"
	"context"
	"errors"
	"io"
	"net"
	"strings"
	"sync"

	"example.com/kv/proto"
	"example.com/kv/store"
)

// maxLine is the maximum request line length, including the trailing
// newline.
const maxLine = 64 * 1024

// Serve accepts TCP connections on l and serves the store with
// proto.Exec until ctx is cancelled. On cancellation it closes the
// listener, closes all open connections, waits for the connection
// goroutines to finish and returns nil.
func Serve(ctx context.Context, l net.Listener, s *store.Store) error {
	var (
		mu    sync.Mutex
		conns = make(map[net.Conn]struct{})
		wg    sync.WaitGroup
	)
	finished := make(chan struct{})
	go func() {
		<-ctx.Done()
		l.Close()
		mu.Lock()
		for c := range conns {
			c.Close()
		}
		mu.Unlock()
		wg.Wait()
		close(finished)
	}()

	for {
		c, err := l.Accept()
		if err != nil {
			if ctx.Err() != nil {
				<-finished
				return nil
			}
			return err
		}
		mu.Lock()
		conns[c] = struct{}{}
		mu.Unlock()
		wg.Add(1)
		go func(c net.Conn) {
			defer wg.Done()
			defer c.Close()
			defer func() {
				mu.Lock()
				delete(conns, c)
				mu.Unlock()
			}()
			serveConn(c, s)
		}(c)
	}
}

func serveConn(c net.Conn, s *store.Store) {
	br := bufio.NewReader(c)
	for {
		line, err := br.ReadString('\n')
		if isQuit(line) {
			c.Write([]byte("+BYE\n"))
			return
		}
		if err != nil {
			if err != io.EOF {
				// Connection is broken; if we still have data it
				// has already been processed above.
			}
			return
		}
		if len(line) > maxLine {
			c.Write([]byte("-ERR line too long\n"))
			return
		}
		resp := proto.Exec(s, line)
		if _, err := c.Write([]byte(resp)); err != nil {
			return
		}
	}
}

// isQuit reports whether the first token of the request line is the
// QUIT command (case-insensitive).
func isQuit(line string) bool {
	line = strings.TrimSuffix(line, "\n")
	line = strings.TrimSuffix(line, "\r")
	i := 0
	for i < len(line) && (line[i] == ' ' || line[i] == '\t') {
		i++
	}
	start := i
	for i < len(line) && line[i] != ' ' && line[i] != '\t' {
		i++
	}
	if start == i {
		return false
	}
	return strings.EqualFold(line[start:i], "quit")
}

