{"content":"package server

import (
	"bufio"
	"context"
	"fmt"
	"net"
	"os"
	"strings"
	"testing"
	"time"

	"example.com/kv/proto"
	"example.com/kv/store"
)

// client is a raw TCP client helper.
type client struct {
	c net.Conn
	r *bufio.Reader
}

func dialClient(t *testing.T, addr string) *client {
	t.Helper()
	c, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	return &client{c: c, r: bufio.NewReader(c)}
}

func (cl *client) roundTrip(t *testing.T, in string, wantLines ...string) {
	t.Helper()
	if _, err := cl.c.Write([]byte(in + "\n")); err != nil {
		t.Fatal(err)
	}
	var got []string
	for len(got) < len(wantLines) {
		line, err := cl.r.ReadString('\n')
		if err != nil {
			t.Fatalf("reading response: %v", err)
		}
		got = append(got, line)
	}
	for i := range got {
		if got[i] != wantLines[i] {
			t.Fatalf("response %d = %q, want %q", i, got[i], wantLines[i])
		}
	}
}

func (cl *client) close() { cl.c.Close() }

func startServer(t *testing.T) (addr string, cancel context.CancelFunc) {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	go func() {
		if err := Serve(ctx, l, store.New(nil)); err != nil {
			t.Errorf("Serve returned %v", err)
		}
	}()
	// Serve may report listener-closed errors in some setups; the
	// test only checks behaviour via the client.
	return l.Addr().String(), cancel
}

func TestRoundTrip(t *testing.T) {
	addr, cancel := startServer(t)
	defer cancel()
	cl := dialClient(t, addr)
	defer cl.close()
	cl.roundTrip(t, "PING", "+PONG\n")
	cl.roundTrip(t, "SET a b", "+OK\n")
	cl.roundTrip(t, "GET a", "$b\n")
	cl.roundTrip(t, "SET \"k v\" x", "+OK\n")
	cl.roundTrip(t, `GET "k v"`, "$x\n")
	cl.roundTrip(t, "GET missing", "$nil\n")
	cl.roundTrip(t, "INCR n", ":1\n")
	cl.roundTrip(t, "KEYS *", "*3\n$a\n$k v\n$n\n")
	cl.roundTrip(t, "DBSIZE", ":3\n")
}

func TestCRLF(t *testing.T) {
	addr, cancel := startServer(t)
	defer cancel()
	cl := dialClient(t, addr)
	defer cl.close()
	cl.roundTrip(t, "PING", "+PONG\n") // \n only, with a trailing \r variant below
	// Send \r\n explicitly.
	if _, err := cl.c.Write([]byte("SET x y\r\n")); err != nil {
		t.Fatal(err)
	}
	line, err := cl.r.ReadString('\n')
	if err != nil || line != "+OK\n" {
		t.Fatalf("CRLF response = %q, %v", line, err)
	}
	if line2, err := cl.r.ReadString('\n'); err != nil || line2 != "$y\n" {
		t.Fatalf("GET response = %q, %v", line2, err)
	}
}

func TestQuit(t *testing.T) {
	addr, cancel := startServer(t)
	defer cancel()
	cl := dialClient(t, addr)
	defer cl.close()
	cl.roundTrip(t, "QUIT", "+BYE\n")
	// Connection is closed: further reads get EOF and the conn is
	// done.
	cl.c.SetReadDeadline(time.Now().Add(2 * time.Second))
	if _, err := cl.r.ReadString('\n'); err == nil {
		t.Fatal("expected EOF after QUIT")
	}
	// The server must keep serving other clients.
	cl2 := dialClient(t, addr)
	defer cl2.close()
	cl2.roundTrip(t, "PING", "+PONG\n")
}

func TestTooLongLine(t *testing.T) {
	addr, cancel := startServer(t)
	defer cancel()
	cl := dialClient(t, addr)
	defer cl.close()
	long := strings.Repeat("a", maxLine) // exceeds the limit with its newline
	if _, err := cl.c.Write([]byte(long + "\n")); err != nil {
		t.Fatal(err)
	}
	line, err := cl.r.ReadString('\n')
	if err != nil {
		t.Fatal(err)
	}
	if line != "-ERR line too long\n" {
		t.Fatalf("response = %q", line)
	}
	// Connection must be closed.
	cl.c.SetReadDeadline(time.Now().Add(2 * time.Second))
	if _, err := cl.r.ReadString('\n'); err == nil {
		t.Fatal("expected EOF after long line")
	}
}

func TestConcurrentClients(t *testing.T) {
	addr, cancel := startServer(t)
	defer cancel()
	for i := 0; i < 10; i++ {
		i := i
		go func() {
			cl := dialClient(t, addr)
			defer cl.close()
			cl.roundTrip(t, fmt.Sprintf("SET k%d v", i), "+OK\n")
			cl.roundTrip(t, fmt.Sprintf("GET k%d", i), "$v\n")
		}()
	}
	// Give the clients a moment, then check the server still works.
	time.Sleep(100 * time.Millisecond)
	cl := dialClient(t, addr)
	defer cl.close()
	cl.roundTrip(t, "DBSIZE", ":10\n")
}

func TestCancel(t *testing.T) {
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	type result struct{ err error }
	resCh := make(chan result, 1)
	go func() { resCh <- result{Serve(ctx, l, store.New(nil))} }()

	cl := dialClient(t, l.Addr().String())
	cl.roundTrip(t, "PING", "+PONG\n")

	deadline := time.Now().Add(5 * time.Second)
	cancel()
	select {
	case res := <-resCh:
		if res.err != nil {
			t.Fatalf("Serve after cancel = %v, want nil", res.err)
		}
	case <-time.After(time.Until(deadline)):
		t.Fatal("Serve did not return after cancel")
	}
	// The still-open client connection must have been closed.
	cl.c.SetReadDeadline(time.Now().Add(2 * time.Second))
	if _, err := cl.r.ReadString('\n'); err == nil {
		t.Fatal("expected the connection to be closed on cancel")
	}
}

func TestQuitOnlyOnFirstToken(t *testing.T) {
	addr, cancel := startServer(t)
	defer cancel()
	cl := dialClient(t, addr)
	defer cl.close()
	// A key named "quit" must NOT trigger QUIT.
	cl.roundTrip(t, `SET quit x`, "+OK\n")
	cl.roundTrip(t, `GET quit`, "$x\n")
	cl.roundTrip(t, "QUIT", "+BYE\n")
}

